crates/kerotakis-core/src/solution_optic:
//! Shared optical accounting for observations and instruments.
//!
//! An analytical component is not a chromophore concentration. When a native
//! distribution exists, use its molality and its own solvent mass. Never
//! assign the free ion's spectrum to its complexes.
use crate::{species, stoich, vessel::Vessel, Phase, SpeciesId};

fn same_species(native: &str, key: &str) -> bool {
    if native == key {
        return true;
    }
    let Some(data) = species::lookup(&SpeciesId::new(key)) else {
        return false;
    };
    // Formula-key ions permit charge-spelling aliases (Cu+2 / Cu2+).
    // Named organics must not be identified merely by empirical formula.
    if data.key != data.formula {
        return false;
    }
    match (
        stoich::parse_formula(native),
        stoich::parse_formula(data.formula),
    ) {
        (Ok(a), Ok(b)) => a == b,
        _ => false,
    }
}

pub(crate) fn visible_moles(vessel: &Vessel, key: &str, analytical: f64) -> f64 {
    let measured = vessel.solution.as_ref().and_then(|solution| {
        let kg = solution
            .solvent_kg
            .filter(|kg| kg.is_finite() && *kg > 0.0)?;
        let data = species::lookup(&SpeciesId::new(key))?;
        let formula = stoich::parse_formula(data.formula).ok()?;
        if formula.charge == 0.0 || solution.species.is_empty() {
            return None;
        }
        let represented = solution.species.iter().any(|s| {
            stoich::parse_formula(&s.name)
                .ok()
                .is_some_and(|f| formula.counts.keys().all(|el| f.counts.contains_key(el)))
        });
        represented.then(|| {
            solution
                .species
                .iter()
                .filter(|s| same_species(&s.name, key))
                .map(|s| s.molality.max(0.0) * kg)
                .sum::<f64>()
        })
    });
    measured.unwrap_or_else(|| {
        (analytical - crate::surface_colour::sequestered_moles(vessel, &SpeciesId::new(key)))
            .max(0.0)
    })
}

/// Missing spectra for native species containing a known chromophore element.
/// This is a coverage warning, not a claim that each such species is coloured.
pub fn spectral_gaps(vessel: &Vessel) -> Vec<String> {
    let Some(solution) = &vessel.solution else {
        return Vec::new();
    };
    let elements: std::collections::BTreeSet<_> = species::REGISTRY
        .iter()
        .filter(|s| s.spectrum.is_some())
        .filter_map(|s| stoich::parse_formula(s.formula).ok())
        .filter(|f| f.charge != 0.0)
        .flat_map(|f| f.counts.into_keys())
        .filter(|el| !matches!(el.as_str(), "H" | "O" | "C" | "N" | "S"))
        .collect();
    solution
        .species
        .iter()
        .filter(|s| s.molality > 1e-9)
        .filter(|s| {
            stoich::parse_formula(&s.name)
                .ok()
                .is_some_and(|f| f.counts.keys().any(|el| elements.contains(el)))
        })
        .filter(|s| {
            !species::REGISTRY
                .iter()
                .any(|data| data.spectrum.is_some() && same_species(&s.name, data.key))
        })
        .map(|s| s.name.clone())
        .collect()
}

pub fn absorbance(vessel: &Vessel, path_cm: f64) -> [f64; crate::spectrum::BANDS] {
    let mut result = [0.0; crate::spectrum::BANDS];
    let litres = vessel.liquid_volume().0.max(1e-9);
    for portion in &vessel.contents {
        if !matches!(portion.phase, Phase::Aqueous | Phase::Liquid) {
            continue;
        }
        let key = &portion.species.0;
        let spectrum = if crate::indicator::is_ph_dependent(key) {
            vessel
                .solution
                .as_ref()
                .and_then(|s| crate::indicator::spectrum_at_ph(key, s.ph))
        } else {
            species::lookup(&portion.species)
                .and_then(|s| s.spectrum)
                .copied()
        };
        let Some(spectrum) = spectrum else {
            continue;
        };
        let concentration = visible_moles(vessel, key, portion.moles.0) / litres;
        for (out, epsilon) in result.iter_mut().zip(spectrum) {
            *out += epsilon * concentration * path_cm;
        }
    }
    // Native complexes need not be analytical inventory components. If a
    // spectrum is registered for one, include it even without a bottle portion.
    if let Some(solution) = &vessel.solution {
        if let Some(kg) = solution.solvent_kg.filter(|kg| kg.is_finite() && *kg > 0.0) {
            for native in &solution.species {
                if let Some(data) = species::REGISTRY
                    .iter()
                    .find(|data| data.spectrum.is_some() && same_species(&native.name, data.key))
                {
                    if vessel.contents.iter().any(|p| {
                        p.species.0 == data.key && matches!(p.phase, Phase::Aqueous | Phase::Liquid)
                    }) {
                        continue;
                    }
                    for (out, epsilon) in result.iter_mut().zip(data.spectrum.unwrap()) {
                        *out += epsilon * native.molality.max(0.0) * kg / litres * path_cm;
                    }
                }
            }
        }
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        vessel::{SolutionInfo, SpeciesDetail},
        Moles, VesselId,
    };

    #[test]
    fn complexes_do_not_inherit_the_free_ions_absorption() {
        let mut v = Vessel::new(VesselId(0), "beaker");
        v.deposit(SpeciesId::new("water"), Moles(5.55), Phase::Liquid);
        v.deposit(SpeciesId::new("Cu+2"), Moles(0.01), Phase::Aqueous);
        let total_spectrum = absorbance(&v, 1.0);
        assert!(total_spectrum.iter().any(|x| *x > 0.0));
        v.solution = Some(SolutionInfo {
            solvent_kg: Some(0.1),
            ph: 9.0,
            pe: None,
            redox: vec![],
            ionic_strength: 0.1,
            provenance: None,
            species: vec![
                SpeciesDetail {
                    name: "Cu+2".into(),
                    molality: 0.001,
                    activity: 0.0005,
                },
                SpeciesDetail {
                    name: "Cu(NH3)4+2".into(),
                    molality: 0.099,
                    activity: 0.05,
                },
            ],
        });
        let free_spectrum = absorbance(&v, 1.0);
        for (free, total) in free_spectrum.iter().zip(total_spectrum) {
            assert!((free - total * 0.01).abs() < 1e-12);
        }
        assert_eq!(spectral_gaps(&v), vec!["Cu(NH3)4+2"]);
        assert!(crate::appearance::observe(&v)
            .words
            .contains("Colour is incomplete"));
        v.solution.as_mut().unwrap().species.remove(0);
        assert_eq!(absorbance(&v, 1.0), [0.0; crate::spectrum::BANDS]);
    }

    #[test]
    fn beer_lambert_uses_molarity_and_path_length_not_molality() {
        use crate::instrument::Spectrophotometer;
        for amount in [1e-6, 1e-4, 1e-2] {
            let mut v = Vessel::new(VesselId(0), "beaker");
            v.deposit(SpeciesId::new("water"), Moles(5.55), Phase::Liquid);
            v.deposit(SpeciesId::new("MnO4-"), Moles(amount), Phase::Aqueous);
            let one = absorbance(&v, 1.0);
            for path in [0.1, 0.5, 2.0, 10.0] {
                let measured = Spectrophotometer { path_cm: path }.measure_spectrum(&v);
                for (a, b) in measured.iter().zip(one) {
                    assert!((a - b * path).abs() < 1e-10);
                }
            }
        }
    }
}

crates/kerotakis-core/tests/organic_equi:
//! The explicit equilibrium request must solve arbitrary initial inventories,
//! including excess water and reverse hydrolysis, without prescribed yields.
use kerotakis_core::*;

#[test]
fn ester_equilibrium_obeys_mass_action_and_conservation_across_1280_mixtures() {
    let mut checked = 0;
    for scale in [1e-6, 1e-3, 1.0, 10.0, 1000.0] {
        for acid in [0.0, 0.1, 1.0, 10.0] {
            for alcohol in [0.0, 0.1, 1.0, 10.0] {
                for ester in [0.0, 0.1, 1.0, 10.0] {
                    for water in [0.0, 0.1, 1.0, 10.0] {
                        let mut bench = Bench::new();
                        let v = &mut bench.vessels[0];
                        for (key, n) in [
                            ("CH3COOH", acid),
                            ("ethanol", alcohol),
                            ("ethyl_acetate", ester),
                            ("water", water),
                        ] {
                            v.deposit(
                                SpeciesId::new(key),
                                Moles(n * scale),
                                species::lookup_key(key).unwrap().standard_phase,
                            );
                        }
                        let before = ledger::ConservedLedger::from_vessel(v);
                        // No solver stack: isolate the requested equilibrium from
                        // evaporation and aqueous dissociation (separate laws).
                        let mut solver = SolverStack::new(vec![]);
                        bench
                            .step_with(
                                Operator::React {
                                    vessel: VesselId(0),
                                    reaction: "esterification".into(),
                                },
                                &mut solver,
                                &PermissiveScreen,
                            )
                            .unwrap();
                        let v = &bench.vessels[0];
                        let after = ledger::ConservedLedger::from_vessel(v);
                        for (el, n) in before.elements {
                            assert!(
                                (after.elements.get(&el).copied().unwrap_or(0.0) - n).abs()
                                    < 1e-10 + n.abs() * 1e-10
                            );
                        }
                        let n = |key| v.moles_of(&SpeciesId::new(key)).0;
                        let r = n("CH3COOH") * n("ethanol");
                        let p = n("ethyl_acetate") * n("water");
                        if r > scale * scale * 1e-12 && p > scale * scale * 1e-12 {
                            assert!(
                                (p / r - 4.0).abs() < 1e-4,
                                "initial [{acid}, {alcohol}, {ester}, {water}] × {scale}: Q={}",
                                p / r
                            );
                        }
                        checked += 1;
                    }
                }
            }
        }
    }
    assert_eq!(checked, 1280);
}

crates/kerotakis-phreeqc/src/complexatio:
//! Reviewed reference-temperature ligand slice shared by aqueous databases.
//!
//! Native mass action, charge balance and activity corrections compute the
//! distribution for arbitrary totals. These are not scenario-specific yields.
//! See data/thermo/usbm-ic9429-complexes.dat and its provenance review. The
//! source supplies 25 C constants only: callers must disclose that temperature
//! derivatives, reaction heat, rates and complex spectra remain unknown.

pub const SOURCE_ID: &str = "usbm-ic9429-complexes-25c";
pub const REFERENCE_TEMPERATURE_K: f64 = 298.15;
pub const EXTENSION: &[u8] = include_bytes!("../../../data/thermo/usbm-ic9429-complexes.dat");

/// Translate exact native pseudo-component names to physical species names.
///
/// Thiocyanate is an independently conserved ligand in the native database,
/// not a chemical element. Public reports must expose its actual formula so
/// downstream composition and spectral-coverage checks can identify it.
pub fn native_to_physical(name: &str) -> &str {
    match name {
        "Thiocyanate-" => "SCN-",
        "Fe(Thiocyanate)+2" => "Fe(SCN)+2",
        "Fe(Thiocyanate)2+" => "Fe(SCN)2+",
        _ => name,
    }
}

/// Native or physical names whose constants belong to this reviewed slice.
pub fn uses_reference_complexes(name: &str) -> bool {
    matches!(
        native_to_physical(name),
        "CuNH3+2" | "Cu(NH3)2+2" | "Cu(NH3)3+2" | "Cu(NH3)4+2" | "Fe(SCN)+2" | "Fe(SCN)2+"
    )
}

/// Append before the final END; bytes after END are not read by PHREEQC.
pub fn append_to(database: &[u8]) -> Vec<u8> {
    let insert_at = super::databases::find_last_end(database).unwrap_or(database.len());
    let mut bytes = Vec::with_capacity(database.len() + EXTENSION.len() + 1);
    bytes.extend_from_slice(&database[..insert_at]);
    bytes.push(b'\n');
    bytes.extend_from_slice(EXTENSION);
    bytes.extend_from_slice(&database[insert_at..]);
    bytes
}

/// True only at the measured reference temperature (numerical tolerance, not
/// an invented experimental validity interval).
pub fn temperature_covered(temperature_k: f64) -> bool {
    temperature_k.is_finite() && (temperature_k - REFERENCE_TEMPERATURE_K).abs() < 1e-8
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn physical_aliases_are_exact_and_preserve_reference_coverage() {
        for (native, physical) in [
            ("Thiocyanate-", "SCN-"),
            ("Fe(Thiocyanate)+2", "Fe(SCN)+2"),
            ("Fe(Thiocyanate)2+", "Fe(SCN)2+"),
        ] {
            assert_eq!(native_to_physical(native), physical);
            assert_eq!(native_to_physical(physical), physical);
            assert_eq!(
                uses_reference_complexes(native),
                uses_reference_complexes(physical)
            );
        }
        for name in ["Fe(SCN)+2", "Fe(SCN)2+", "Cu(NH3)4+2"] {
            assert!(uses_reference_complexes(name));
        }
        for name in [
            "Thiocyanate",
            "SCN-",
            "Fe(Thiocyanate)3",
            "XThiocyanate-",
            "Cu+2",
        ] {
            assert_eq!(native_to_physical(name), name);
            assert!(!uses_reference_complexes(name));
        }
    }

    #[test]
    fn extension_precedes_end_and_does_not_claim_temperature_derivatives() {
        for ending in ["END\n", "END", "  END\r\n"] {
            let source = format!("SOLUTION_SPECIES\nH+ = H+\n log_k 0\n{ending}");
            let text = String::from_utf8(append_to(source.as_bytes())).unwrap();
            assert!(text.find("Cu(NH3)4+2").unwrap() < text.rfind("END").unwrap());
            assert!(!text.contains("delta_h"));
        }
        assert!(temperature_covered(298.15));
        for t in [298.0, 300.0, f64::NAN, f64::INFINITY] {
            assert!(!temperature_covered(t));
        }
    }
}

crates/kerotakis-phreeqc/src/inventory.r:
//! Conservative change from full speciation to the analytical inventory.
//!
//! PHREEQC's solvent belongs to its full species distribution. Analytical
//! component totals require their own H/O balance. Complete that basis with
//! H2O and acid/base equivalents, not a correction to the scale. These
//! equivalents are not free-ion measurements: SolutionInfo remains authoritative
//! for activities, pH, and free_proton/free_hydroxide.
use kerotakis_core::{
    ledger::ConservedLedger, species, Event, Moles, Phase, Portion, SolveError, SpeciesId, Vessel,
};

pub(crate) fn complete_basis(
    before: &Vessel,
    after: &mut Vessel,
    events: &[Event],
    reservoirs: &[&str],
) -> Result<(), SolveError> {
    let mut target = ConservedLedger::from_vessel(before).elements;
    for event in events {
        let (id, amount) = match event {
            Event::GasEvolved { species, moles, .. } => (species, -moles.0),
            Event::GasAbsorbed { species, moles, .. }
                if reservoirs.contains(&species.0.as_str()) =>
            {
                (species, moles.0)
            }
            _ => continue,
        };
        if let Some(formula) =
            species::lookup(id).and_then(|s| kerotakis_core::stoich::parse_formula(s.formula).ok())
        {
            for (element, count) in formula.counts {
                *target.entry(element).or_default() += amount * count;
            }
        }
    }
    after.contents.retain(|p| {
        !(p.phase == Phase::Aqueous && matches!(p.species.0.as_str(), "H+" | "OH-"))
            && !(p.phase == Phase::Liquid && p.species.0 == "water")
    });
    let booked = ConservedLedger::from_vessel(after).elements;
    let remaining =
        |el: &str| target.get(el).copied().unwrap_or(0.0) - booked.get(el).copied().unwrap_or(0.0);
    let oxygen = remaining("O");
    let hydrogen = remaining("H");
    // w+b=O; 2w+a+b=H. Choose the nonnegative acid/base representation.
    // Autoionization is in speciation and is not duplicated in this basis.
    let excess = hydrogen - 2.0 * oxygen;
    let acid = excess.max(0.0);
    let base = (-excess).max(0.0);
    let water = oxygen - base;
    if !water.is_finite() || water < -1e-9 || !acid.is_finite() || !base.is_finite() {
        return Err(SolveError::NotConverged {
            solver: "phreeqc-inventory".into(),
            detail: format!(
                "no nonnegative aqueous basis conserves H/O: residual H={hydrogen}, O={oxygen}"
            ),
        });
    }
    for (key, amount, phase) in [
        ("water", water.max(0.0), Phase::Liquid),
        ("H+", acid, Phase::Aqueous),
        ("OH-", base, Phase::Aqueous),
    ] {
        if amount > 1e-12 {
            after.contents.push(Portion {
                species: SpeciesId::new(key),
                moles: Moles(amount),
                phase,
            });
        }
    }
    Ok(())
}

crates/kerotakis-phreeqc/src/native_name:
//! Translate the adapter's physical names at the native component boundary.
use crate::redox_isolation::IsolatedDatabase;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::OnceLock;

pub(crate) fn database(tag: &str) -> Result<&'static IsolatedDatabase, String> {
    static WATEQ: OnceLock<Result<IsolatedDatabase, String>> = OnceLock::new();
    static MINTEQ: OnceLock<Result<IsolatedDatabase, String>> = OnceLock::new();
    static PITZER: OnceLock<Result<IsolatedDatabase, String>> = OnceLock::new();
    let (slot, bytes) = match tag {
        "wateq4f" => (&WATEQ, crate::databases::wateq4f()),
        "minteq.v4" => (&MINTEQ, crate::databases::minteq_v4()),
        "pitzer" => (&PITZER, crate::databases::PITZER),
        _ => return Err(format!("unknown native database {tag}")),
    };
    slot.get_or_init(|| crate::redox_isolation::transform(bytes))
        .as_ref()
        .map_err(Clone::clone)
}

pub(crate) fn fingerprint(tag: &str) -> Result<&'static str, String> {
    static WATEQ: OnceLock<Result<String, String>> = OnceLock::new();
    static MINTEQ: OnceLock<Result<String, String>> = OnceLock::new();
    static PITZER: OnceLock<Result<String, String>> = OnceLock::new();
    let slot = match tag {
        "wateq4f" => &WATEQ,
        "minteq.v4" => &MINTEQ,
        "pitzer" => &PITZER,
        _ => return Err(format!("unknown native database {tag}")),
    };
    slot.get_or_init(|| database(tag).map(|db| kerotakis_data::snapshot_sha256(&db.database)))
        .as_ref()
        .map(String::as_str)
        .map_err(Clone::clone)
}

fn words(text: &str, mut replace: impl FnMut(&str) -> String) -> String {
    let mut out = String::new();
    for part in text.split_inclusive(char::is_whitespace) {
        let word = part.trim_end_matches(char::is_whitespace);
        out.push_str(&replace(word));
        out.push_str(&part[word.len()..]);
    }
    out
}

pub(crate) fn input(db: &IsolatedDatabase, source: &str) -> String {
    let mut result = String::new();
    let mut section = "";
    for line in source.lines() {
        let mut tokens = line.split_whitespace();
        let first = tokens.next().unwrap_or("");
        if matches!(
            first,
            "SOLUTION"
                | "SOLUTION_SPECIES"
                | "PHASES"
                | "SELECTED_OUTPUT"
                | "EQUILIBRIUM_PHASES"
                | "GAS_PHASE"
                | "SOLID_SOLUTIONS"
                | "SURFACE"
                | "EXCHANGE"
                | "MIX"
                | "REACTION"
                | "SAVE"
                | "END"
                | "TITLE"
        ) {
            section = first;
        }
        if first == "-totals" {
            let mut selected = BTreeSet::new();
            for token in tokens {
                if matches!(token, "N" | "S") && db.totals.contains_key(token) {
                    for (key, internal) in &db.totals {
                        if key.starts_with(&format!("{token}(")) {
                            selected.insert(internal.clone());
                        }
                    }
                } else {
                    selected.insert(
                        db.totals
                            .get(token)
                            .cloned()
                            .unwrap_or_else(|| token.into()),
                    );
                }
            }
            result.push_str("    -totals ");
            result.push_str(&selected.into_iter().collect::<Vec<_>>().join(" "));
        } else if section == "SOLUTION" {
            // Only the first field is a component name; following fields
            // may name a gas/phase buffer and must retain their public names.
            let mut first_word = true;
            result.push_str(&words(line, |word| {
                if word.is_empty() {
                    return String::new();
                }
                let replace = first_word;
                first_word = false;
                if replace {
                    db.totals.get(word).cloned().unwrap_or_else(|| word.into())
                } else {
                    word.into()
                }
            }));
        } else if (section == "SOLUTION_SPECIES" && line.contains('='))
            || (section == "PHASES" && line.contains('='))
            || matches!(section, "EXCHANGE" | "SURFACE")
            || matches!(first, "-molalities" | "-activities")
        {
            result.push_str(&words(line, |word| {
                db.species.get(word).cloned().unwrap_or_else(|| word.into())
            }));
        } else {
            // A phase name can also be an aqueous species name (CuSO4).
            // Phase selection/output and solid-solution component names are
            // not chemical formula fields and must never be renamed.
            result.push_str(line);
        }
        result.push('\n');
    }
    result
}

/// Restore exact species tokens, never substrings (N is not Na or Nitrate).
pub(crate) fn report(db: &IsolatedDatabase, native: &str) -> String {
    let reverse: BTreeMap<_, _> = db
        .species
        .iter()
        .map(|(p, n)| (n.as_str(), p.as_str()))
        .collect();
    words(native, |word| {
        crate::complexation::native_to_physical(reverse.get(word).copied().unwrap_or(word)).into()
    })
}

pub(crate) fn selected(db: &IsolatedDatabase, mut rows: Vec<Vec<String>>) -> Vec<Vec<String>> {
    let Some(native_header) = rows.first().cloned() else {
        return rows;
    };
    let mut physical = BTreeMap::new();
    for (name, internal) in &db.totals {
        if let Some((element, state)) = name.split_once('(') {
            if let Ok(state) = state.trim_end_matches(')').parse::<i32>() {
                physical.insert(internal.as_str(), format!("{element}({state})"));
            }
        }
    }
    let species: BTreeMap<_, _> = db
        .species
        .iter()
        .map(|(p, n)| (n.as_str(), p.as_str()))
        .collect();
    for header in &mut rows[0] {
        let trimmed = header.trim();
        *header = if let Some(name) = physical.get(trimmed) {
            name.clone()
        } else if let Some((prefix, native)) = trimmed.split_once('_') {
            if matches!(prefix, "m" | "la" | "a") {
                format!(
                    "{prefix}_{}",
                    crate::complexation::native_to_physical(
                        species.get(native).copied().unwrap_or(native)
                    )
                )
            } else {
                trimmed.into()
            }
        } else {
            trimmed.into()
        };
    }
    for element in ["N", "S"] {
        let expected: BTreeSet<_> = db.totals.iter()
            .filter(|(key, _)| key.starts_with(&format!("{element}(")))
            .map(|(_, internal)| internal.as_str()).collect();
        if expected.is_empty() || !expected.iter().all(|name|
            native_header.iter().any(|column| column.trim() == *name)) {
            // A requested oxidation state is not necessarily the complete
            // element. Never label a partial column sum as an element total.
            continue;
        }
        let columns: Vec<_> = native_header
            .iter()
            .enumerate()
            .filter_map(|(i, name)| {
                physical
                    .get(name.trim())
                    .filter(|key| key.starts_with(&format!("{element}(")))
                    .map(|_| i)
            })
            .collect();
        if columns.is_empty() {
            continue;
        }
        rows[0].push(element.into());
        for row in rows.iter_mut().skip(1) {
            let sum: Option<f64> = columns
                .iter()
                .map(|&i| row.get(i)?.trim().parse::<f64>().ok())
                .sum();
            row.push(
                sum.map(|n| format!("{n:.16e}"))
                    .unwrap_or_else(|| "NaN".into()),
            );
        }
    }
    rows
}

#[cfg(test)]
mod tests {
    use super::*;
    fn fixture() -> IsolatedDatabase {
        IsolatedDatabase {
            database: vec![],
            totals: BTreeMap::from([
                ("N".into(), "Noxfive".into()),
                ("N(5)".into(), "Noxfive".into()),
                ("N(-3)".into(), "Nredthree".into()),
            ]),
            species: BTreeMap::from([
                ("NH4+".into(), "NredthreeH4+".into()),
                ("NH3".into(), "NredthreeH3".into()),
            ]),
        }
    }
    #[test]
    fn totals_species_and_similar_names_keep_distinct_meanings() {
        let db = fixture();
        let translated = input(&db, "SOLUTION 1\n N(-3) 0.01\n Na 0.02\nSELECTED_OUTPUT\n -totals N N(-3) N(5) Na\n -molalities NH3 NH4+\nEND\n");
        assert!(translated.contains("Nredthree 0.01"));
        assert!(translated.contains("Na 0.02"));
        assert!(translated.contains("-totals Na Noxfive Nredthree"));
        assert!(translated.contains("-molalities NredthreeH3 NredthreeH4+"));
        assert_eq!(
            report(&db, " NredthreeH3 0.01\n Na+ 0.02\n"),
            " NH3 0.01\n Na+ 0.02\n"
        );
        let rows = selected(
            &db,
            vec![
                vec!["Noxfive".into(), "Nredthree".into(), "m_NredthreeH3".into()],
                vec!["0.002".into(), "0.003".into(), "0.001".into()],
            ],
        );
        assert_eq!(rows[0], ["N(5)", "N(-3)", "m_NH3", "N"]);
        assert!((rows[1][3].parse::<f64>().unwrap() - 0.005).abs() < 1e-14);
    }

    #[test]
    fn a_phase_name_is_not_an_aqueous_species_formula() {
        let mut db = fixture();
        db.species.insert("CuSO4".into(), "CuSoxsixO4".into());
        let source = "EQUILIBRIUM_PHASES 1\n CuSO4 0 0.01\nGAS_PHASE 1\n N2(g) 0.8\nSOLID_SOLUTIONS 1\n mix\n -comp1 CuSO4 0.01\nSELECTED_OUTPUT\n -equilibrium_phases CuSO4\n -saturation_indices CuSO4\n -molalities CuSO4\nEND\n";
        let translated = input(&db, source);
        assert_eq!(
            translated,
            source.replace("-molalities CuSO4", "-molalities CuSoxsixO4")
        );
    }

    #[test]
    fn a_partial_state_selection_does_not_invent_an_element_total() {
        let rows = selected(&fixture(), vec![vec!["Nredthree".into()], vec!["0.003".into()]]);
        assert_eq!(rows[0], ["N(-3)"]);
        assert_eq!(rows[1], ["0.003"]);
    }
}

crates/kerotakis-phreeqc/src/phase_diagn:
//! Explain unoffered thermodynamic phases without inventing precipitation kinetics.
use crate::derived;
use kerotakis_core::{ops::NotModelledCause, species, Event, VesselId};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Exclusion {
    GasBoundary,
    TemperatureWithheld,
    RegisteredExcluded,
    MissingSolid,
    UnknownPhase,
}

fn classify(phase: &str, db_tag: &str, temperature_k: f64) -> Exclusion {
    let Some(info) = derived::index_for(db_tag).phases.get(phase) else {
        return Exclusion::UnknownPhase;
    };
    if info.is_gas {
        return Exclusion::GasBoundary;
    }
    // The candidate list deliberately omits some registered solids (for
    // example elemental metals owned by electron-balanced displacement).
    // Registry coverage is a composition question, not candidate membership.
    let Some(key) = derived::registry_solid_matching(&info.composition, info.waters) else {
        return Exclusion::MissingSolid;
    };
    if species::lookup_key(key)
        .and_then(|s| s.forms_only_above_k)
        .is_some_and(|floor| temperature_k < floor)
    {
        Exclusion::TemperatureWithheld
    } else {
        Exclusion::RegisteredExcluded
    }
}

fn describe(list: &[(&str, f64)]) -> String {
    let first = list
        .iter()
        .take(3)
        .map(|(name, si)| format!("{name} (SI {si:+.1})"))
        .collect::<Vec<_>>()
        .join(", ");
    match list.len().saturating_sub(3) {
        0 => first,
        n => format!("{first}, and {n} more"),
    }
}

/// Diagnose only unoffered finite indices above the caller's reporting floor.
/// Gas SI uses the database reference fugacity, not the vessel's total pressure;
/// a positive value alone is not a bubble-formation or transfer-rate prediction.
pub(crate) fn events(
    vessel: VesselId,
    temperature_k: f64,
    db_tag: &str,
    saturation: &[(String, f64)],
    offered: &[&str],
    reporting_si: f64,
) -> Vec<Event> {
    let mut result = Vec::new();
    for category in [
        Exclusion::MissingSolid,
        Exclusion::TemperatureWithheld,
        Exclusion::RegisteredExcluded,
        Exclusion::GasBoundary,
        Exclusion::UnknownPhase,
    ] {
        let mut phases: Vec<_> = saturation
            .iter()
            .filter(|(name, si)| {
                si.is_finite()
                    && *si >= reporting_si
                    && !offered.contains(&name.as_str())
                    && classify(name, db_tag, temperature_k) == category
            })
            .map(|(name, si)| (name.as_str(), *si))
            .collect();
        if phases.is_empty() {
            continue;
        }
        phases.sort_by(|a, b| b.1.total_cmp(&a.1).then(a.0.cmp(b.0)));
        let named = describe(&phases);
        let (cause, what) = match category {
            Exclusion::MissingSolid => (
                NotModelledCause::PhaseNotInRegistry,
                format!("the solution is supersaturated against {named}. These solid phases are in {db_tag}.dat but have no matching solid in this lab's registry, so their precipitation is not included. Supersaturation alone does not determine whether or how fast a precipitate forms"),
            ),
            Exclusion::TemperatureWithheld => (
                NotModelledCause::ModelBoundary,
                format!("the solution is supersaturated against {named}, deliberately withheld below the registry's formation-temperature threshold at {:.0} °C. This is a curated metastability boundary, not a computed nucleation or growth rate", temperature_k - 273.15),
            ),
            Exclusion::RegisteredExcluded => (
                NotModelledCause::ModelBoundary,
                format!("the solution is supersaturated against {named}. Matching solids exist in this lab's registry but were not offered in this aqueous equilibrium problem; phase selection, oxidation-state restrictions, or another model's ownership can exclude them. Their formation and its timescale are not predicted by these saturation indices"),
            ),
            Exclusion::GasBoundary => (
                NotModelledCause::ModelBoundary,
                format!("{named} are gas-phase saturation indices relative to the thermodynamic database's reference fugacity, not missing precipitates. Interpret them with this vessel's gas boundary and pressure; these indices alone predict neither bubble formation nor gas-transfer times"),
            ),
            Exclusion::UnknownPhase => (
                NotModelledCause::ModelBoundary,
                format!("{named} have reported saturation indices but no phase definition in the selected {db_tag} diagnostic index; their phase type and exclusion reason cannot be classified"),
            ),
        };
        result.push(Event::NotYetModeled {
            cause,
            vessel,
            what,
        });
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn registry_coverage_is_not_candidate_coverage() {
        for tag in ["wateq4f", "minteq.v4", "pitzer"] {
            for (name, phase) in &derived::index_for(tag).phases {
                let expected = if phase.is_gas {
                    Exclusion::GasBoundary
                } else if derived::registry_solid_matching(&phase.composition, phase.waters)
                    .is_some()
                {
                    Exclusion::RegisteredExcluded
                } else {
                    Exclusion::MissingSolid
                };
                assert_eq!(classify(name, tag, 1e6), expected, "{tag}: {name}");
            }
        }
        assert_eq!(
            classify("Hematite", "wateq4f", 298.15),
            Exclusion::RegisteredExcluded
        );
        assert_eq!(classify("N2(g)", "wateq4f", 298.15), Exclusion::GasBoundary);
    }

    #[test]
    fn temperature_boundary_is_checked_not_merely_present() {
        let floor = species::lookup_key("CuO")
            .unwrap()
            .forms_only_above_k
            .unwrap();
        assert_eq!(
            classify("Tenorite", "wateq4f", floor - 1.0),
            Exclusion::TemperatureWithheld
        );
        for temperature in [floor, floor + 1.0, floor + 100.0] {
            assert_eq!(
                classify("Tenorite", "wateq4f", temperature),
                Exclusion::RegisteredExcluded
            );
        }
    }

    #[test]
    fn offered_small_and_invalid_indices_do_not_generate_boundaries() {
        let input = vec![
            ("N2(g)".into(), 5.0),
            ("Hematite".into(), 0.5),
            ("Tenorite".into(), f64::NAN),
            ("unknown".into(), f64::INFINITY),
        ];
        assert!(events(VesselId(0), 298.15, "wateq4f", &input, &["N2(g)"], 1.0).is_empty());
    }

    #[test]
    fn gases_and_registered_solids_are_never_reported_as_missing_precipitates() {
        let input = vec![("N2(g)".into(), 5.0), ("Hematite".into(), 4.0)];
        let output = events(VesselId(0), 298.15, "wateq4f", &input, &[], 1.0);
        assert_eq!(output.len(), 2);
        for event in &output {
            assert!(matches!(
                event,
                Event::NotYetModeled {
                    cause: NotModelledCause::ModelBoundary,
                    ..
                }
            ));
        }
        let serialized = serde_json::to_string(&output).unwrap();
        assert!(serialized.contains("reference fugacity"));
        assert!(serialized.contains("Matching solids exist"));
        assert!(!serialized.contains("would not stay like this"));
    }
}

crates/kerotakis-phreeqc/src/redox_isola:
//! Native slow-redox isolation by separate conserved master components.
//!
//! USGS PHREEQC Example 4 and the PHREEQC FAQ require separate elements to
//! prevent homogeneous redox equilibration during a batch reaction or MIX.
//! This transformation changes the component namespace, not equilibrium
//! constants for acid/base or complex formation. Public names remain physical.
//!
//! Primary documentation (no numeric constants imported):
//! <https://water.usgs.gov/water-resources/software/PHREEQC/documentation/phreeqc3-html/phreeqc3-66.htm>
//! <https://wwwbrr.cr.usgs.gov/projects/GWC_coupled/phreeqc.v1/faq.html>
use std::collections::{BTreeMap, BTreeSet};

#[derive(Debug)]
pub struct IsolatedDatabase {
    pub database: Vec<u8>,
    pub totals: BTreeMap<String, String>,
    pub species: BTreeMap<String, String>,
}

type Counts = BTreeMap<String, f64>;

#[derive(Debug)]
struct Reaction {
    line: usize,
    section: String,
    lhs: Vec<(String, f64)>,
    rhs: Vec<(String, f64)>,
}

fn terms(side: &str) -> Result<Vec<(String, f64)>, String> {
    let mut result = Vec::new();
    let mut coefficient = 1.0;
    for token in side.split_whitespace() {
        if token == "+" {
            continue;
        }
        if token == "-" {
            coefficient = -1.0;
            continue;
        }
        if let Ok(number) = token.parse::<f64>() {
            coefficient *= number;
            continue;
        }
        let split = token
            .find(|c: char| c.is_ascii_alphabetic() || c == '[' || c == '(')
            .unwrap_or(0);
        let (number, name) = token.split_at(split);
        if !number.is_empty() {
            coefficient *= number
                .parse::<f64>()
                .map_err(|_| format!("unsupported reaction term {token}"))?;
        }
        result.push((name.to_string(), coefficient));
        coefficient = 1.0;
    }
    Ok(result)
}

fn pseudo(element: &str, state: i32) -> String {
    let digits = [
        "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
    ];
    let suffix = state
        .unsigned_abs()
        .to_string()
        .bytes()
        .map(|b| digits[(b - b'0') as usize])
        .collect::<String>();
    format!("{element}{}{suffix}", if state < 0 { "red" } else { "ox" })
}

fn add(into: &mut Counts, from: &Counts, scale: f64) {
    for (key, value) in from {
        *into.entry(key.clone()).or_default() += scale * value;
    }
}

fn composition(name: &str) -> Option<Counts> {
    if let Some((base, hydrate)) = name.split_once(':') {
        let mut result = composition(base)?;
        let end = hydrate
            .find(|c: char| !c.is_ascii_digit() && c != '.')
            .unwrap_or(0);
        let n = if end == 0 {
            1.0
        } else {
            hydrate[..end].parse::<f64>().ok()?
        };
        add(&mut result, &composition(&hydrate[end..])?, n);
        return Some(result);
    }
    kerotakis_core::stoich::parse_formula_with(
        name,
        kerotakis_core::stoich::FormulaDialect::PhreeqcMaster,
    )
    .ok()
    .map(|f| f.counts)
}

fn slow_count(name: &str) -> f64 {
    element_tokens(name)
        .iter()
        .filter(|e| matches!(e.as_str(), "N" | "S"))
        .count() as f64
}

fn element_tokens(name: &str) -> Vec<String> {
    let bytes = name.as_bytes();
    let mut result = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i].is_ascii_uppercase() {
            let start = i;
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_lowercase() {
                i += 1;
            }
            result.push(name[start..i].to_string());
        } else {
            i += 1;
        }
    }
    result
}

fn inferred(reaction: &Reaction, known: &BTreeMap<String, Counts>) -> Option<Counts> {
    let mut result = Counts::new();
    for (name, coefficient) in &reaction.lhs {
        add(&mut result, known.get(name)?, *coefficient);
    }
    for (name, coefficient) in reaction.rhs.iter().skip(1) {
        add(&mut result, known.get(name)?, -*coefficient);
    }
    let coefficient = reaction.rhs.first()?.1;
    for value in result.values_mut() {
        *value /= coefficient;
    }
    result.retain(|_, value| value.abs() > 1e-10);
    (result.values().all(|n| *n >= 0.0)).then_some(result)
}

fn rename_formula(name: &str, states: &Counts) -> Result<String, String> {
    if states.is_empty() {
        return Ok(name.to_string());
    }
    let elements = element_tokens(name);
    let mut replacements = BTreeMap::new();
    for element in ["N", "S"] {
        if !elements.iter().any(|e| e == element) {
            continue;
        }
        let components: Vec<_> = states
            .iter()
            .filter(|(key, _)| key.starts_with(element))
            .collect();
        if components.len() != 1 {
            return Err(format!(
                "mixed or unresolved {element} states within species {name}: {states:?}"
            ));
        }
        replacements.insert(element, components[0].0.as_str());
    }
    let bytes = name.as_bytes();
    let mut out = String::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i].is_ascii_uppercase() {
            let start = i;
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_lowercase() {
                i += 1;
            }
            let element = &name[start..i];
            out.push_str(replacements.get(element).copied().unwrap_or(element));
        } else {
            out.push(bytes[i] as char);
            i += 1;
        }
    }
    Ok(out)
}

fn replace_tokens(line: &str, aliases: &BTreeMap<String, String>) -> String {
    let mut out = String::new();
    let mut start = 0;
    for (i, ch) in line.char_indices() {
        if ch.is_whitespace() {
            if start < i {
                let token = &line[start..i];
                out.push_str(aliases.get(token).map(String::as_str).unwrap_or(token));
            }
            out.push(ch);
            start = i + ch.len_utf8();
        }
    }
    if start < line.len() {
        let token = &line[start..];
        out.push_str(aliases.get(token).map(String::as_str).unwrap_or(token));
    }
    out
}

fn render_terms(terms: &[(String, f64)], aliases: &BTreeMap<String, String>) -> String {
    let mut out = String::new();
    for (name, n) in terms {
        if !out.is_empty() {
            out.push_str(if *n < 0.0 { " - " } else { " + " });
        } else if *n < 0.0 {
            out.push('-');
        }
        if n.abs() != 1.0 {
            out.push_str(&format!("{} ", n.abs()));
        }
        out.push_str(aliases.get(name).unwrap_or(name));
    }
    out
}

/// Transform the selected database, including reviewed appended extensions.
/// Unsupported unresolved state-bearing reactions are errors, not a fallback
/// to the original redox-equilibrating database.
pub fn transform(bytes: &[u8]) -> Result<IsolatedDatabase, String> {
    // PHREEQC databases are byte-oriented, with Latin-1 in comments.
    let text: String = bytes.iter().map(|b| char::from(*b)).collect();
    let lines: Vec<_> = text.lines().collect();
    let mut section = String::new();
    let mut master_rows = Vec::new();
    let mut phase_headers = BTreeSet::new();
    let mut reactions = Vec::new();
    let mut masses = BTreeMap::new();
    for (line, source) in lines.iter().enumerate() {
        let content = source.split('#').next().unwrap_or("").trim();
        if content.is_empty() {
            continue;
        }
        if matches!(
            content,
            "SOLUTION_MASTER_SPECIES"
                | "SOLUTION_SPECIES"
                | "PHASES"
                | "EXCHANGE_MASTER_SPECIES"
                | "EXCHANGE_SPECIES"
                | "SURFACE_MASTER_SPECIES"
                | "SURFACE_SPECIES"
                | "RATES"
                | "PITZER"
                | "SIT"
                | "NAMED_EXPRESSIONS"
                | "END"
        ) {
            section = content.to_string();
            continue;
        }
        if section == "SOLUTION_MASTER_SPECIES" {
            let fields: Vec<_> = content.split_whitespace().collect();
            if fields.len() >= 4 && matches!(fields[0].split('(').next(), Some("N" | "S")) {
                if !fields[0].contains('(') && fields.len() >= 5 {
                    masses.insert(fields[0].to_string(), fields[4].to_string());
                }
                master_rows.push((
                    line,
                    fields.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
                ));
            }
        }
        if matches!(
            section.as_str(),
            "SOLUTION_SPECIES" | "PHASES" | "EXCHANGE_SPECIES" | "SURFACE_SPECIES"
        ) {
            if let Some((lhs, rhs)) = content.split_once('=') {
                if section == "PHASES" {
                    // PHREEQC permits indentation and a trailing reference
                    // number on phase names (for example `MnSO4 182`). The
                    // last meaningful line before its equation is the name;
                    // lexical resemblance to an aqueous formula is irrelevant.
                    let header = (0..line)
                        .rev()
                        .find(|i| !lines[*i].split('#').next().unwrap_or("").trim().is_empty())
                        .ok_or_else(|| "phase equation without a phase name".to_string())?;
                    phase_headers.insert(header);
                }
                let rhs = rhs.split(';').next().unwrap_or(rhs);
                reactions.push(Reaction {
                    line,
                    section: section.clone(),
                    lhs: terms(lhs)?,
                    rhs: terms(rhs)?,
                });
            }
        }
    }
    let mut totals = BTreeMap::new();
    let mut known = BTreeMap::new();
    let mut promoted = BTreeSet::new();
    let mut edits = BTreeMap::new();
    for (line, fields) in &master_rows {
        let Some((element, oxidation)) = fields[0].split_once('(') else {
            edits.insert(*line, String::new());
            continue;
        };
        let state = oxidation
            .trim_end_matches(')')
            .parse::<i32>()
            .map_err(|_| format!("invalid state {}", fields[0]))?;
        let component = pseudo(element, state);
        let counts =
            composition(&fields[1]).ok_or_else(|| format!("master formula {}", fields[1]))?;
        let count = *counts
            .get(element)
            .ok_or_else(|| format!("master missing element {}", fields[1]))?;
        known.insert(
            fields[1].clone(),
            BTreeMap::from([(component.clone(), count)]),
        );
        promoted.insert(fields[1].clone());
        totals.insert(format!("{element}({state})"), component.clone());
        totals.insert(format!("{element}({state:+})"), component.clone());
        let mass = masses
            .get(element)
            .ok_or_else(|| format!("missing atomic weight {element}"))?;
        edits.insert(
            *line,
            format!("{component} {} {} {mass} {mass}", fields[1], fields[2]),
        );
    }
    for (_, fields) in &master_rows {
        if !fields[0].contains('(') {
            let key = known
                .get(&fields[1])
                .and_then(|counts| counts.keys().next())
                .ok_or_else(|| {
                    format!(
                        "primary master has no declared oxidation state {}",
                        fields[1]
                    )
                })?;
            totals.insert(fields[0].clone(), key.clone());
        }
    }
    for reaction in &reactions {
        for (name, _) in reaction.lhs.iter().chain(&reaction.rhs) {
            if slow_count(name) == 0.0 {
                known.entry(name.clone()).or_default();
            }
        }
    }
    loop {
        let mut progress = false;
        for reaction in reactions.iter().filter(|r| r.section != "PHASES") {
            let Some((name, _)) = reaction.rhs.first() else {
                continue;
            };
            if known.contains_key(name) {
                continue;
            }
            if let Some(mut states) = inferred(reaction, &known) {
                // Native polysulfide mass action can consume one HS- while
                // its explicit mass balance carries several sulfur atoms.
                // Membership follows the reaction; multiplicity follows the
                // species formula, not a fictitious one-sulfur molecule.
                if let Some(counts) = composition(name) {
                    for element in ["N", "S"] {
                        let components: Vec<_> = states
                            .keys()
                            .filter(|k| k.starts_with(element))
                            .cloned()
                            .collect();
                        if components.len() == 1 {
                            if let Some(count) = counts.get(element) {
                                states.insert(components[0].clone(), *count);
                            }
                        }
                    }
                }
                known.insert(name.clone(), states);
                progress = true;
            }
        }
        if !progress {
            break;
        }
    }
    let mut species = BTreeMap::new();
    for reaction in &reactions {
        for (name, _) in reaction.lhs.iter().chain(&reaction.rhs) {
            if let Some(states) = known.get(name) {
                let renamed = rename_formula(name, states)?;
                if renamed != *name {
                    species.insert(name.clone(), renamed);
                }
            } else if reaction.section == "SOLUTION_SPECIES" {
                return Err(format!("unresolved oxidation-state membership of {name}"));
            }
        }
    }
    let mut reverse = BTreeMap::new();
    for (physical, internal) in &species {
        if let Some(previous) = reverse.insert(internal, physical) {
            return Err(format!("internal species alias collision: {previous} and {physical} both map to {internal}"));
        }
    }
    // Mineral and gas formula membership comes from its dissolution products,
    // not nominal elemental charge. Use the native reaction's stoichiometry.
    for reaction in reactions.iter().filter(|r| r.section == "PHASES") {
        let Some((formula, coefficient)) = reaction.lhs.first() else {
            continue;
        };
        if slow_count(formula) == 0.0 {
            continue;
        }
        let mut states = Counts::new();
        for (name, n) in &reaction.rhs {
            add(
                &mut states,
                known
                    .get(name)
                    .ok_or_else(|| format!("unresolved phase product {name}"))?,
                *n / coefficient,
            );
        }
        for (name, n) in reaction.lhs.iter().skip(1) {
            add(
                &mut states,
                known
                    .get(name)
                    .ok_or_else(|| format!("unresolved phase reactant {name}"))?,
                -*n / coefficient,
            );
        }
        if states.values().any(|n| !n.is_finite() || *n < -1e-10) {
            return Err(format!(
                "invalid isolated phase composition for {formula}: {states:?}"
            ));
        }
        // A phase formula may contain multiple oxidation states (NH4NO3).
        // Serialize physical non-N/S counts and the separately conserved pools.
        let mut formula_counts =
            composition(formula).ok_or_else(|| format!("phase formula {formula}"))?;
        formula_counts.remove("N");
        formula_counts.remove("S");
        add(&mut formula_counts, &states, 1.0);
        let renamed = formula_counts
            .iter()
            .filter(|(_, n)| **n > 1e-10)
            .map(|(element, n)| {
                if *n == 1.0 {
                    element.clone()
                } else {
                    format!("{element}{n}")
                }
            })
            .collect::<String>();
        let mut lhs = reaction.lhs.clone();
        lhs[0].0 = renamed;
        let render = |terms: &[(String, f64)]| render_terms(terms, &species);
        edits.insert(
            reaction.line,
            format!("    {} = {}", render(&lhs), render(&reaction.rhs)),
        );
    }
    for reaction in reactions.iter().filter(|r| r.section == "SOLUTION_SPECIES") {
        let name = &reaction.rhs[0].0;
        if promoted.contains(name) {
            let alias = species.get(name).unwrap_or(name);
            edits.insert(reaction.line, format!("{alias} = {alias}\n log_k 0"));
            let end = reactions
                .iter()
                .find(|r| r.line > reaction.line)
                .map_or(lines.len(), |r| r.line);
            for i in reaction.line + 1..end {
                let parameter = lines[i]
                    .trim()
                    .trim_start_matches('-')
                    .split_whitespace()
                    .next()
                    .unwrap_or("")
                    .to_ascii_lowercase();
                if matches!(
                    parameter.as_str(),
                    "log_k"
                        | "logk"
                        | "delta_h"
                        | "deltah"
                        | "analytical_expression"
                        | "analytic"
                        | "a_e"
                        | "add_logk"
                        | "add_log_k"
                ) {
                    edits.insert(i, String::new());
                }
            }
        }
    }
    for reaction in &reactions {
        if edits.contains_key(&reaction.line) {
            continue;
        }
        let render = |terms: &[(String, f64)]| render_terms(terms, &species);
        let suffix = lines[reaction.line]
            .split('#')
            .next()
            .unwrap_or("")
            .split_once(';')
            .map(|(_, rest)| format!(";{rest}"))
            .unwrap_or_default();
        edits.insert(
            reaction.line,
            format!(
                "    {} = {}{suffix}",
                render(&reaction.lhs),
                render(&reaction.rhs)
            ),
        );
    }
    let mut output = String::new();
    for (i, line) in lines.iter().enumerate() {
        let line = edits.get(&i).map(String::as_str).unwrap_or(line);
        let line = if phase_headers.contains(&i) {
            line.to_string()
        } else {
            replace_tokens(line, &species)
        };
        // Explicit valence mass balances (polysulfides) also use isolated pools.
        let mut rewritten = line;
        for (physical, internal) in &totals {
            if physical.contains('(') {
                rewritten = rewritten.replace(physical, internal);
            }
        }
        output.push_str(&rewritten);
        output.push('\n');
    }
    Ok(IsolatedDatabase {
        database: output.chars().map(|c| c as u8).collect(),
        totals,
        species,
    })
}

